/**
 * Single effects on the characteristic, roll, ability and permission axes, as one
 * lowercase-initial clause with no period. The board axes (protection, models, moves,
 * placement, tests, resources, designation, army) are in `effect-leaf-board.ts`.
 */

import { describeBoardLeaf } from "./effect-leaf-board.js";
import { abilityClassState, describeShapeLeaf } from "./effect-leaf-shapes.js";
import {
  abilityLabel, andList, bracketKeyword, dekebab, diceCase, effectSubject, hasWeapon, isPlural, jstr, ofOrPossessive, orList, pronoun,
  movedPhrase, noneOf, rangePhrase, regionPhrase, rollName, signed, statName, titleCase, v, weaponHolder, weaponLabel, weaponNoun,
  weaponRollScope, type Ctx,
  isRatingRef,
} from "./effect-words.js";
import { describeCondition, type Condition } from "./condition.js";
import type { P } from "./condition-refs.js";
import { selectionBinding, selectorSubject, selectUnitsSubject } from "./effect-bind.js";
import { expiryTrail } from "./expiry.js";
import { addedOptionRecipients, orderShare, ordersModifier } from "./effect-orders.js";

/** A leaf effect node: `{type, target, modifier, scaling?}`. */
export interface Leaf {
  type?: string;
  target?: unknown;
  modifier?: Record<string, unknown>;
}

/** Renders a nested effect inline (supplied by the container describer). */
export type Inline = (e: unknown, ctx: Ctx) => string;

/** Every single-effect type; anything else is a container. */
export const LEAF_TYPES = new Set([
  "stat-modifier", "ignore-modifiers", "roll-modifier", "re-roll", "roll-result", "end-attack-sequence", "ability-grant",
  "keyword-grant", "weapon-ability-grant", "weapon-ability-range", "weapon-grant", "ability-modifier", "ability-activate", "permission", "targeting",
  "counts-as", "rule-state", "mortal-wounds", "damage-reduction", "feel-no-pain", "invulnerable-save", "heal", "return-models",
  "destroy-models", "act-on-death", "split-unit", "add-unit", "destruction-rule", "move", "move-modifier", "set-up", "marker",
  "transport-capacity", "test", "state-change", "cp-gain", "cost-modifier", "resource-gain", "resource-gain-cap", "resource-spend", "resource-die",
  "objective-sticky", "region-extend", "designate", "army-rule", "test-exemption", "datasheet-swap", "characteristic-resolution", "borrow-weapons", "select-weapon",
  "oath-modifier", "orders-modifier", "order-share", "reserves-schedule",
]);

/** "each time an attack targets the unit, " — the lead of an `incoming` change. */
function incomingLead(m: Record<string, unknown>, subj: string): string {
  const scope = m.weapons as P | undefined;
  const attack = scope?.type != null && Object.keys(scope).length === 1 ? `a ${jstr(scope.type)} attack` : hasWeapon(m) ? `an attack with ${weaponNoun(m)}` : "an attack";
  return `each time ${attack} targets ${subj}, `;
}

/** A stat change as a verb phrase over `what` ("add 1 to the unit's Toughness characteristic"). */
function statChange(m: Record<string, unknown>, what: string): string {
  const op = jstr(m.operation);
  // A Range is printed in inches ("a Range characteristic of 18\"").
  if (op === "set") return `set ${what} to ${diceCase(m.value)}${m.stat === "Range" ? "\"" : ""}`;
  if (op === "halve") return `halve ${what}`;
  if (op === "multiply") return `multiply ${what} by ${diceCase(m.value)}`;
  if (op === "improve" || op === "worsen") return `${op} ${what} by ${diceCase(m.value)}`;
  let verb = op === "subtract" ? "subtract" : "add";
  let val: unknown = m.value;
  const n = Number(val);
  if (!Number.isNaN(n) && n < 0) {
    verb = verb === "add" ? "subtract" : "add";
    val = Math.abs(n);
  }
  return `${verb} ${diceCase(val)} ${verb === "add" ? "to" : "from"} ${what}`;
}

/** Characteristics a model rolls against, where a better value is a lower number ("3+"). */
const ROLL_TARGET_STATS = new Set(["Sv", "WS", "BS", "Ld"]);
/** Characteristics measured in inches. */
const DISTANCE_STATS = new Set(["M", "Range", "detection-range"]);

function bounds(m: Record<string, unknown>): string {
  // An improved roll target is capped from below: "this cannot improve a model's Save to better than 3+".
  if (m.operation === "improve" && ROLL_TARGET_STATS.has(String(m.stat)) && m.minimum != null && m.maximum == null) return `, to no better than ${jstr(m.minimum)}+`;
  const min = m.minimum != null ? `, to a minimum of ${jstr(m.minimum)}` : "";
  const max = m.maximum != null ? `, to a maximum of ${jstr(m.maximum)}` : "";
  return min + max;
}

/** The characteristics an attack has: under an `attackers-of-target` designation, each attack's. */
const ATTACK_STATS = new Set(["S", "WS", "BS", "AP", "D"]);

/**
 * Which attacks against the target a per-attack change covers: " if it is made with ranged weapons
 * by a friendly ASTRA MILITARUM unit". A target that is any friendly unit or model, or the attacking
 * unit, adds nothing: every such attack already qualifies.
 */
function attackMaker(target: unknown, m: Record<string, unknown>, subj: string): string {
  const withWeapons = hasWeapon(m) ? ` with ${weaponNoun(m)}` : "";
  const f = target != null && typeof target === "object" && !Array.isArray(target) ? (target as P) : undefined;
  const refKeys = ["selection_var", "event_var", "stratagem_target", "aura_recipient", "role"];
  // A null field is an absent one.
  const isFilter = f != null && !refKeys.some((k) => f[k] != null);
  const anyAttacker = target == null || target === "attacker" || (isFilter && Object.keys(f).every((k) => f[k] == null || (k === "owner" && f.owner === "friendly") || k === "level"));
  const maker = anyAttacker ? "" : isFilter ? selectorSubject({ filter: f }, false) : subj;
  const by = maker === "" ? "" : ` by ${isFilter ? `${/^[aeiou]/i.test(maker) ? "an" : "a"} ${maker}` : maker}`;
  return withWeapons || by ? ` if it is made${withWeapons}${by}` : "";
}

/** " (this is not cumulative with …)": what a modifier does not stack with, after the change it qualifies. */
function notCumulativeTrail(m: Record<string, unknown>, of: string): string {
  const nc = m.not_cumulative;
  if (nc === "negative-modifiers") return ` (this is not cumulative with any other negative modifiers to that ${of})`;
  if (nc != null && typeof nc === "object" && (nc as P).ability != null) return ` (this is not cumulative with the ${abilityLabel((nc as P).ability)} ability)`;
  return "";
}

function statModifier(e: Leaf, m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  const statKey = jstr(m.stat);
  // AP is printed negative; the DSL stores its magnitude.
  if (statKey === "AP" && m.operation === "set" && typeof m.value === "number" && m.value > 0) m = { ...m, value: `-${m.value}` };
  // Roll-target stats (Sv, WS, BS, Ld) set to a number print with a trailing "+" ("2+").
  if (ROLL_TARGET_STATS.has(statKey) && m.operation === "set" && typeof m.value === "number") m = { ...m, value: `${m.value}+` };
  // Distance stats (M, Range, detection-range) print with inches on add/subtract/set.
  if (DISTANCE_STATS.has(statKey) && (m.operation === "add" || m.operation === "subtract" || m.operation === "set") && (typeof m.value === "number" || (typeof m.value === "string" && !m.value.endsWith('"')))) {
    m = { ...m, value: `${diceCase(m.value)}"` };
  }
  const stat = statKey === "detection-range" ? "detection range" : `${statName(m.stat)} characteristic`;
  const nc = notCumulativeTrail(m, "characteristic");
  if (m.incoming === true) return `${incomingLead(m, subj)}${statChange(m, `the ${stat} of that attack`)}${bounds(m)}${nc}`;
  if (ctx.attackOnTarget && ATTACK_STATS.has(statKey)) return `${statChange(m, `the ${stat} of that attack`)}${bounds(m)}${attackMaker(e.target, m, subj)}${nc}`;
  if (hasWeapon(m)) return `${statChange(m, `the ${stat} of ${weaponNoun(m)} equipped by ${weaponHolder(e.target, ctx)}`)}${bounds(m)}${nc}`;
  if (e.target === "attacker" && ATTACK_STATS.has(statKey)) return `${statChange(m, `the ${stat} of the attacking unit's attacks`)}${bounds(m)}${nc}`;
  return `${statChange(m, ofOrPossessive(subj, stat))}${bounds(m)}${nc}`;
}

function ignoreModifiers(m: Record<string, unknown>, subj: string): string {
  const kind = m.only === "worsening" ? "negative " : m.only === "improving" ? "positive " : "";
  const things =
    m.what === "rolls"
      ? Array.isArray(m.rolls) && !m.rolls.some((r) => r === "all" || r === "any") ? `${andList((m.rolls as unknown[]).map(rollName))} rolls` : "rolls"
      : Array.isArray(m.stats) ? `${andList((m.stats as unknown[]).map(statName))} characteristics` : "characteristics";
  // "any roll (excluding modifiers to saving throws)": the rolls whose modifiers still apply.
  const except = m.what === "rolls" && Array.isArray(m.except_rolls) && m.except_rolls.length ? ` (except ${andList((m.except_rolls as unknown[]).map(rollName))} rolls)` : "";
  // "you can ignore any or all modifiers to …": the player picks which modifiers to ignore, keeping any it wants.
  const which = m.choice === "any-or-all" ? "any or all" : "any";
  if (m.incoming === true) return `${incomingLead(m, subj)}ignore ${which} ${kind}modifiers to that attack's ${things}${except}`;
  if (m.choice === "any-or-all") return `you can ignore any or all ${kind}modifiers to ${ofOrPossessive(subj, things)}${except}${weaponRollScope(m)}`;
  return `${subj} ${v(subj, "ignores")} any ${kind}modifiers to ${pronoun(subj)} ${things}${except}${weaponRollScope(m)}`;
}

const ATTACK_ROLLS = new Set(["hit", "wound", "damage"]);

/** Whether a weapon filter only restates the enclosing `while making <type> attacks` condition. */
function suppressedWeaponScope(m: Record<string, unknown>, ctx: Ctx): string {
  if (!hasWeapon(m)) return "";
  const w = m.weapons as P;
  if (ctx.suppressWeaponType && w.type === ctx.suppressWeaponType && Object.keys(w).length === 1) return "";
  return weaponRollScope(m);
}

function rollModifier(m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  return `${rollModifierChange(m, subj, ctx)}${notCumulativeTrail(m, "roll")}`;
}

function rollModifierChange(m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  // A bound roll's result as the value ("add 1 for each of those mortal wounds", one roll for both).
  const bound = typeof m.value === "object" && m.value !== null && typeof (m.value as P).roll_var === "string" && (m.value as P).successes_on == null;
  const boundValue = m.value_from === "previous-roll" || bound ? "the result of that roll" : null;
  const cap = m.cap != null ? `, to a maximum of ${signed(m.operation, m.cap)}` : "";
  const rn = jstr(m.roll);
  const rolls = `${rollName(m.roll)} rolls`;
  const scope = suppressedWeaponScope(m, ctx);
  // "Halve Advance and Charge rolls made for that unit": the result is halved, with no value.
  if (m.operation === "halve") return `halve ${ofOrPossessive(subj, rolls)}${scope}`;
  let sub = m.operation === "subtract" || m.operation === "worsen";
  let rawVal: unknown = m.value;
  const num = Number(rawVal);
  if (!boundValue && !Number.isNaN(num) && num < 0) {
    sub = !sub;
    rawVal = Math.abs(num);
  }
  const verb = sub ? "subtract" : "add";
  const prep = sub ? "from" : "to";
  const val = boundValue ?? diceCase(rawVal);
  if (m.incoming === true) {
    return `${incomingLead(m, subj)}${verb} ${val} ${prep} the ${rollName(m.roll)} roll${cap}`;
  }
  return `${verb} ${val} ${prep} ${ofOrPossessive(subj, rolls)}${scope}${cap}`;
}

function reRoll(e: Leaf, m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  const rn = jstr(m.roll);
  const noun = rn === "any" ? "roll" : `${rollName(m.roll)} roll`;
  const isAttackRoll = ATTACK_ROLLS.has(rn);
  const cnt = typeof m.count === "number" ? m.count : undefined;
  // A counted allowance ("one for each model equipped with …") reads as a number of rolls.
  const counted = m.count != null && typeof m.count === "object" ? `a number of ${failedNoun(m, noun)}s equal to ${diceCase(m.count)}` : undefined;
  const failed = m.subset === "all-failures" ? "failed " : "";
  const which =
    counted != null
      ? counted
      : cnt != null
      ? `${cnt === 1 ? "one" : `up to ${cnt}`} ${failed}${noun}${cnt === 1 ? "" : "s"}${m.subset === "ones" ? " of 1" : m.subset === "ones-and-twos" ? " of 1 or 2" : ""}`
      : isAttackRoll
        ? m.subset === "ones"
          ? `${noun}s of 1`
          : m.subset === "ones-and-twos"
            ? `${noun}s of 1 or 2`
            : m.subset === "all-failures"
              ? `failed ${noun}s`
              : `${noun}s`
        : m.subset === "ones"
          ? `${rn === "any" ? "any" : "a"} ${noun} of 1`
          : m.subset === "ones-and-twos"
            ? `${rn === "any" ? "any" : "a"} ${noun} of 1 or 2`
            : m.subset === "all-failures"
              ? `a failed ${noun}`
              : rn === "any" ? "any roll" : `the ${noun}`;
  const pool = m.pool != null ? ` by spending a die from your ${titleCase(jstr(m.pool))}` : "";
  const can = m.mandatory === true ? "must" : "can";
  const scope = suppressedWeaponScope(m, ctx);
  if (m.incoming === true) return `${incomingLead(m, subj)}the attacking player ${can} re-roll ${which}${pool}`;
  // "you can re-roll …" names whose roll it is unless that is the ability's own unit.
  const own = e.target == null || e.target === "this-unit" || e.target === "attacker" || (e.target === "recipient" && !ctx.auraRecipient);
  const model = e.target === "this-model" || (e.target === "selected-unit" && ctx.selectedModel);
  const holder = model ? weaponHolder(e.target, ctx) : subj;
  const owner = own ? "" : ` for ${isAttackRoll ? "attacks made by " : ""}${holder}`;
  return `you ${can} re-roll ${which}${owner}${scope}${pool}`;
}

function failedNoun(m: Record<string, unknown>, noun: string): string {
  return m.subset === "all-failures" ? `failed ${noun}` : m.subset === "ones" ? `${noun} of 1` : m.subset === "ones-and-twos" ? `${noun} of 1 or 2` : noun;
}

function rollResult(m: Record<string, unknown>, subj: string): string {
  const roll = rollName(m.roll);
  const lead = m.incoming === true ? incomingLead(m, subj) : "";
  // A cap: "if the result is greater than 6 (after modifiers), change it to 6".
  if (m.at_most != null) return `${ofOrPossessive(subj, `${roll} rolls`)}${weaponRollScope(m)} count as ${jstr(m.at_most)} if the result is greater than ${jstr(m.at_most)} after modifiers`;
  if (m.critical_on != null) {
    const crit = m.roll === "wound" ? "Critical Wound" : "Critical Hit";
    if (m.critical_on === "success") return `${lead}each successful ${roll} roll${lead ? "" : ` made by ${subj}`}${weaponRollScope(m)} is a ${crit}`;
    return `${lead}${lead ? "a" : `${subj} ${v(subj, "scores")}`} ${crit}${lead ? "" : "s"} on ${roll} rolls of ${jstr(m.critical_on)}+${weaponRollScope(m)}${lead ? " for that attack" : ""}`;
  }
  if (m.fails_on != null) {
    const n = Number(m.fails_on);
    const range = n === 1 ? "1" : `1-${n}`;
    if (lead) return `${lead}an unmodified ${roll} roll of ${range} for that attack always fails`;
    return `${ofOrPossessive(subj, `${roll} rolls`)}${weaponRollScope(m)} always fail on an unmodified ${range}`;
  }
  if (m.succeeds_on != null) {
    const rolls = lead ? `the ${roll} roll for that attack` : ofOrPossessive(subj, `${roll} rolls`);
    return `${lead}${rolls}${lead ? "" : weaponRollScope(m)} ${lead ? "succeeds" : "succeed"} only on an unmodified ${jstr(m.succeeds_on)}+`;
  }
  const tests = ["battle-shock", "leadership", "desperate-escape"].includes(jstr(m.roll));
  if (tests && !lead) {
    if (m.result === "pass") return `${subj} automatically ${v(subj, "passes")} ${roll} tests`;
    if (m.result === "fail") return `${subj} automatically ${v(subj, "fails")} ${roll} tests`;
  }
  // count 1: one roll the player picks ("change the result of one Hit roll … to an unmodified 6").
  if (m.count === 1 && !lead) {
    const outcome = m.result === "pass" ? "automatically succeeds" : m.result === "fail" ? "automatically fails"
      : `counts as ${m.unmodified === true ? "an unmodified " : ""}${jstr(m.result)}`;
    return `one of ${ofOrPossessive(subj, `${roll} rolls`)}${weaponRollScope(m)} ${outcome}`;
  }
  const whose = lead ? `the ${roll} roll for that attack` : ofOrPossessive(subj, `${roll} rolls`);
  const verb = lead ? { pass: "automatically succeeds", fail: "automatically fails" } : { pass: "automatically succeed", fail: "automatically fail" };
  if (m.result === "pass" || m.result === "fail") return `${lead}${whose}${lead ? "" : weaponRollScope(m)} ${verb[m.result]}`;
  const unmod = m.unmodified === true ? "an unmodified " : "";
  return `${lead}${whose}${lead ? " counts" : `${weaponRollScope(m)} count`} as ${unmod}${jstr(m.result)}`;
}

/** A grant that prints the ability it gives (`modifier.definition`). */
export function isDefinedGrant(e: { type?: string; modifier?: Record<string, unknown> }): boolean {
  return e.type === "ability-grant" && e.modifier?.definition != null && typeof e.modifier.definition === "object";
}

/**
 * "Friendly X units gain the Shade Ward ability": who holds a printed ability and its name, or
 * "the following rules" for an unnamed one. Model targets retain model-only ownership.
 */
export function definedGrantHead(e: Leaf, ctx: Ctx): string {
  const m = e.modifier ?? {};
  const def = m.definition as P;
  const base = effectSubject(e.target, ctx);
  const subj = base;
  const name = typeof def.name === "string" ? def.name : m.ability != null ? abilityLabel(m.ability) : null;
  return name ? `${subj} ${v(subj, "gains")} the ${name} ability` : `${subj} ${v(subj, "gains")} the following rules`;
}

/** The printed ability as a part without its name, which the grant's head already says. */
export function definitionPart(e: Leaf): Record<string, unknown> {
  const { name: _name, ...part } = (e.modifier?.definition ?? {}) as P;
  return part;
}

function abilityGrant(e: Leaf, m: Record<string, unknown>, subj: string, ctx: Ctx, inline: Inline): string {
  if (isDefinedGrant(e)) return `${definedGrantHead(e, ctx)} (${inline(definitionPart(e), ctx)})`;
  // Cover is a state a unit has, not an ability it gains.
  if (m.ability === "benefit-of-cover") return `${subj} ${v(subj, "has")} the Benefit of Cover`;
  const inch = m.ability === "scouts" || m.ability === "deep-strike" ? '"' : "";
  const rated = isRatingRef(m.value);
  const value = m.value != null ? ` ${rated ? "X" : jstr(m.value)}${inch}` : "";
  const noun = m.rules_bundle === true ? "rules" : "ability";
  return `${subj} ${v(subj, "gains")} the ${abilityLabel(m.ability)}${value} ${noun}${rated ? ", X being its rating" : ""}`;
}

function keywordGrant(m: Record<string, unknown>, subj: string): string {
  const kws = Array.isArray(m.keywords) ? (m.keywords as unknown[]).map(jstr) : [];
  const noun = kws.length === 1 ? "keyword" : "keywords";
  const replaces = Array.isArray(m.replaces) ? `, replacing ${pronoun(subj)} ${andList((m.replaces as unknown[]).map(jstr))} ${m.replaces.length === 1 ? "keyword" : "keywords"}` : "";
  return `${subj} ${v(subj, "gains")} the ${andList(kws)} ${noun}${replaces}`;
}

/** Change an existing weapon ability's reach without granting or replacing its rating. */
function weaponAbilityRange(m: Record<string, unknown>, subj: string): string {
  const range = m.range === "weapon" ? "the weapon's range" : rangePhrase(m.range);
  return `${ofOrPossessive(subj, "attacks")}${weaponRollScope(m)} benefit from ${bracketKeyword(m.keyword)} when the target is within ${range}`;
}

function weaponAbilityGrant(e: Leaf, m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  const gained = Array.isArray(m.keywords) ? (m.keywords as unknown[]).map(bracketKeyword).join(" and ") : undefined;
  const lost = Array.isArray(m.removes) ? (m.removes as unknown[]).map(bracketKeyword).join(" and ") : undefined;
  const increment = m.if_present === "increment" ? " (a weapon that already has that ability adds the ratings together)" : "";
  if (m.incoming === true) return `${incomingLead(m, subj)}the attacking weapon has ${gained ?? "[?]"}${increment}`;
  const noun = hasWeapon(m) ? `${weaponNoun(m)} equipped by ${weaponHolder(e.target, ctx)}` : ofOrPossessive(subj, "weapons");
  const plural = !hasWeapon(m) || /weapons\b/.test(weaponNoun(m));
  // A grant and a removal in one effect read "gain X and lose Y"; a neither-list shape keeps the old placeholder.
  const changes = [
    gained && `${plural ? "gain" : "gains"} ${gained}${increment}`,
    lost && `${plural ? "lose" : "loses"} ${lost}`,
  ].filter(Boolean);
  return `${noun} ${changes.length ? changes.join(" and ") : `${plural ? "gain" : "gains"} [?]`}`;
}

const ASPECTS: Record<string, string> = {
  uses: "number of uses", range: "range", targets: "number of targets", recipients: "recipients", selections: "number of selections",
  concurrent: "number that can apply at once", duration: "duration", "start-round": "first battle round", "end-round": "last battle round",
  threshold: "threshold", options: "options", amount: "amount",
};

/** The ability an ability-modifier changes: a named one, the one a trigger used, or those reaching an audience. */
function modifiedAbility(ref: unknown, subj: string, ctx: Ctx): string {
  // A stance option or a definition inside another record is named like a record.
  if (ref != null && typeof ref === "object" && !("ability_id" in ref)) {
    const r = ref as Record<string, unknown>;
    if (r.event === "used") return "that ability";
    if (typeof r.keyword === "string") return `each ${r.keyword} ability of ${subj}`;
    return `each ability of ${subj} that affects ${effectSubject(r.affecting, ctx).replace(/^all /, "")}`;
  }
  return ofOrPossessive(subj, `${abilityLabel(ref)} ability`);
}

function abilityModifier(m: Record<string, unknown>, subj: string, ctx: Ctx, inline: Inline): string {
  if (m.aspect === "selection" && m.operation === "set" && m.selection != null) {
    const selector = m.selection as P;
    const duration = expiryTrail(m.recipient_duration);
    return `replace that ability's selection with ${selectUnitsSubject(selector)}${selectionBinding(selector)}; those recipients are affected by that same ability${duration ? ` ${duration}` : ""}`;
  }
  // "The bearer's unit can be regenerated up to twice per phase": how many times one unit can be affected by it.
  if (m.aspect === "received") return `${subj} can be affected by ${abilityLabel(m.ability)} up to ${timesWord(m.value)}, in place of its usual limit`;
  const whose = modifiedAbility(m.ability, subj, ctx);
  // "If it suffers one or more mortal wounds as a result of that Dark Pact, add 1 to the number of mortal wounds it suffers."
  if (m.aspect === "mortal-wounds") {
    const change = m.operation === "subtract" ? `subtract ${jstr(m.value)} from` : `add ${jstr(m.value)} to`;
    return `if ${whose} inflicts one or more mortal wounds on ${subj}, ${change} the number of mortal wounds it suffers`;
  }
  const aspect = ASPECTS[jstr(m.aspect)] ?? jstr(m.aspect);
  const value = m.aspect === "range" && typeof m.value === "number" ? `${jstr(m.value)}"` : typeof m.value === "string" ? dekebab(m.value) : jstr(m.value);
  const cap = m.cap != null ? ` (to a maximum of ${jstr(m.cap)})` : "";
  const opt = m.add_option as { name?: unknown; eligible?: unknown; effect?: unknown } | undefined;
  const recipients = m.recipients != null ? effectSubject(m.recipients, ctx) : undefined;
  const option = opt != null ? `the option ${titleCase(jstr(opt.name))} (${addedOptionRecipients(opt, ctx)}${inline(opt.effect, ctx)})` : undefined;
  // An add with no value only widens the ability: it names the new recipients or option instead of a count.
  if (m.value == null && m.operation !== "set" && m.operation !== "lift-limit" && (recipients || option)) {
    const parts = [recipients && `${whose} can also affect ${recipients}`, option && `${whose} gains ${option}`].filter(Boolean);
    return parts.join("; ") + cap;
  }
  let s: string;
  switch (m.operation) {
    case "lift-limit": s = `${whose} has no limit on its ${aspect}`; break;
    case "set": s = `the ${aspect} of ${whose} ${m.aspect === "options" || m.aspect === "recipients" ? "are" : "is"} ${value}`; break;
    case "subtract": s = `decrease the ${aspect} of ${whose} by ${value}`; break;
    default: s = `increase the ${aspect} of ${whose} by ${value}`;
  }
  if (recipients) s += `; it can also affect ${recipients}`;
  if (option) s += `; add ${option}`;
  return s + cap + abilityLimits(m);
}

/** "once", "twice", "3 times". */
function timesWord(value: unknown): string {
  const n = Number(value);
  return n === 1 ? "once" : n === 2 ? "twice" : `${jstr(value)} times`;
}

/** The limits on a changed allowance: once per battle round, never in the same phase, outside the shared limit. */
function abilityLimits(m: Record<string, unknown>): string {
  const parts: string[] = [];
  const per = m.cap_per as { count?: unknown; period?: unknown } | undefined;
  if (per != null) parts.push(`but it can be used at most ${Number(per.count) === 1 ? "once" : `${jstr(per.count)} times`} per ${dekebab(jstr(per.period))}`);
  if (m.not_same != null) parts.push(`but not in the same ${jstr(m.not_same)} as the use that triggered this`);
  if (m.consumes_shared_use === false) parts.push("and this use does not count toward that ability's limit for other units");
  return parts.length ? `, ${parts.join(", ")}` : "";
}

const ACTIVITIES: Record<string, string> = {
  shoot: "shoot", "declare-charge": "declare a charge", fight: "fight", "start-action": "start an Action", embark: "embark",
  disembark: "disembark", "fall-back": "Fall Back", advance: "Advance", "use-stratagem": "be targeted with Stratagems",
  "issue-order": "issue Orders", "attempt-ritual": "attempt Rituals", "use-enhancement": "use Enhancements", move: "move", observe: "act as an Observer",
};
const AFTER: Record<string, string> = {
  advance: "Advanced", "fall-back": "Fell Back", disembark: "disembarked", normal: "made a Normal move",
  charge: "made a Charge move", "remain-stationary": "Remained Stationary", "set-up": "was set up",
};
const DESPITE: Record<string, string> = {
  engaged: "within Engagement Range of enemy units", "battle-shocked": "Battle-shocked", "shot-this-phase": "has already shot this phase",
  "fought-this-phase": "has already fought this phase", "disembarked-this-turn": "disembarked this turn",
  "stratagem-used-this-phase": "has already been targeted with that Stratagem this phase", "performing-action": "performing an Action",
  advanced: "Advanced this turn", "fell-back": "Fell Back this turn", destroyed: "has just been destroyed",
  embarked: "embarked within a Transport",
};
const IS_STATE = new Set(["engaged", "battle-shocked", "performing-action", "embarked"]);
const AS_IF: Record<string, string> = {
  "shooting-phase": " as if it were your Shooting phase", "fight-phase": " as if it were the Fight phase", "snap-shooting": " using the Snap Shooting rules",
  "movement-phase": " as if it were your Movement phase", "charge-phase": " as if it were your Charge phase", "command-phase": " as if it were your Command phase",
};

/**
 * "; if it does, it counts as having made a Normal move that phase, and cannot declare a charge
 * this turn": what using the permission does to its subject (counts_as_move, its counts_as_until
 * window, and the activities then_cannot forbids for the rest of the turn).
 */
function permissionConsequences(m: Record<string, unknown>, it: string): string {
  const they = it === "they";
  const lead = `; if ${it} ${they ? "do" : "does"}, ${it}`;
  const cannot = Array.isArray(m.then_cannot)
    ? `cannot ${orList((m.then_cannot as unknown[]).map((a) => ACTIVITIES[jstr(a)] ?? jstr(a)))} this turn`
    : null;
  if (m.counts_as_move != null) {
    const period = m.counts_as_until === "end-of-phase" ? "that phase" : "this turn";
    return `${lead} ${they ? "count" : "counts"} as having made ${movedPhrase(m.counts_as_move)} ${period}${cannot ? `, and ${cannot}` : ""}`;
  }
  return cannot ? `${lead} ${cannot}` : "";
}

function permission(m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  // "You cannot use this Stratagem": a Stratagem's restriction on its own use.
  if (m.activity === "use-stratagem" && m.allow === false && ctx.self !== undefined && m.stratagem === ctx.self) return "you cannot use this Stratagem";
  const it = subj.startsWith("all ") || / units\b/.test(subj) ? "they" : "it";
  const act =
    m.activity === "use-stratagem" && m.stratagem != null
      ? `be targeted with the ${abilityLabel(m.stratagem)} Stratagem`
      : ACTIVITIES[jstr(m.activity)] ?? jstr(m.activity);
  const into = m.into != null ? ` ${m.activity === "shoot" ? "at" : m.activity === "declare-charge" ? "against" : "into"} ${noneOf(effectSubject(m.into, ctx))}` : "";
  const reach = m.reach != null ? ` from up to ${rangePhrase(m.reach)} away` : "";
  const weapons = permissionWeapons(m, isPlural(subj));
  let s = m.allow === false ? `${noneOf(subj)} cannot ${act}${weapons}${into}` : `${subj} ${v(subj, "is")} eligible to ${act}${weapons}${into}${reach}`;
  if (Array.isArray(m.after)) s += ` in a turn in which ${it} ${orList((m.after as unknown[]).map((a) => AFTER[jstr(a)] ?? jstr(a)))}`;
  if (Array.isArray(m.despite)) {
    const clauses = (m.despite as unknown[]).map((d) => {
      // The Transport the subject disembarks from Advanced, not the subject.
      if (jstr(d) === "transport-advanced") return `${it === "they" ? "their" : "its"} Transport Advanced this turn`;
      const phrase = DESPITE[jstr(d)] ?? jstr(d);
      if (IS_STATE.has(jstr(d))) return `${it === "they" ? "they are" : "it is"} ${phrase}`;
      // "they has already shot" → "they have already shot".
      return `${it} ${it === "they" ? phrase.replace(/^has /, "have ") : phrase}`;
    });
    s += ` even if ${orList(clauses)}`;
  }
  if (m.as_if != null) s += AS_IF[jstr(m.as_if)] ?? ` as if ${jstr(m.as_if)}`;
  if (m.next === true) s += `, and must be the next unit selected to ${act}`;
  s += permissionConsequences(m, it);
  if (m.consumes_shared_use === false) s += "; this use does not count toward that Stratagem's once-per-phase limit for other units";
  return s;
}

/**
 * " with its sentry flamer or sentry grenade launcher": the weapons a shoot permission allows, any
 * one of them. Bare names read as the model's own weapons; any other filter reads as a weapon noun.
 */
function permissionWeapons(m: Record<string, unknown>, plural: boolean): string {
  if (!Array.isArray(m.weapons)) return "";
  const scopes = m.weapons as Record<string, unknown>[];
  if (scopes.every((scope) => Object.keys(scope).length === 1 && typeof scope.name === "string")) {
    return ` with ${plural ? "their" : "its"} ${orList(scopes.map((scope) => jstr(scope.name)))}`;
  }
  return ` with ${orList(scopes.map((scope) => weaponNoun({ weapons: scope })))}`;
}

const TARGET_KINDS: Record<string, string> = {
  attack: " with attacks", shoot: " with ranged attacks", fight: " with melee attacks", charge: " with a charge",
  stratagem: " with Stratagems", ability: " with abilities",
};

function targeting(e: Leaf, m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  const who = (m.by != null ? effectSubject(m.by, ctx) : m.target != null ? subj : "units").replace(/^all /, "");
  const attacking = typeof m.by === "object" || who === "units" || isPlural(who) ? (/\bmodels\b/.test(who) ? "the attacking model" : "the attacking unit") : who;
  const whom = m.target === "every-eligible" ? "every eligible target" : m.target != null ? effectSubject(m.target, ctx) : subj;
  // "That enemy unit can then select new charge targets for that charge move": the same action, new targets.
  if (m.may === "reselect") return `${subj} can select new targets for ${m.kind === "charge" ? "that charge" : "those attacks"}`;
  // "That unit cannot be selected by the Noospheric Transference ability": one named ability's selection, by no named unit.
  if (m.kind === "ability" && m.ability != null && m.by == null && m.may !== "redirect") {
    return `${whom} ${m.may === "cannot-target" ? "cannot" : m.may === "must-target" ? "must" : "can"} be selected by the ${abilityLabel(m.ability)} ability`;
  }
  // "Your unit cannot be targeted with the Rapid Ingress Stratagem": a Stratagem ban that names no user.
  if (m.kind === "stratagem" && m.by == null && m.target != null && m.may !== "redirect" && m.target !== "every-eligible") {
    const what = m.stratagem != null ? `the ${abilityLabel(m.stratagem)} Stratagem` : "Stratagems";
    return `${whom} ${m.may === "cannot-target" ? "cannot" : m.may === "must-target" ? "must" : "can"} be targeted with ${what}`;
  }
  const verb = m.may === "cannot-target" ? "cannot target" : m.may === "must-target" ? "must target" : "can target";
  const kind =
    m.kind === "stratagem" && m.stratagem != null
      ? ` with the ${abilityLabel(m.stratagem)} Stratagem`
      : m.kind === "ability" && m.ability != null
        ? ` with the ${abilityLabel(m.ability)} ability`
        : hasWeapon(m) ? ` with ${weaponNoun(m)}` : TARGET_KINDS[jstr(m.kind)] ?? "";
  // not_engaged_with: the targets count as outside that unit's Engagement Range while targets are selected.
  if (m.not_engaged_with != null) {
    const units = whom.replace(/^all /, "");
    return `${units} ${isPlural(units) ? "are" : "is"} not considered to be within Engagement Range of ${effectSubject(m.not_engaged_with, ctx)} when targets are selected${kind}`;
  }
  const rangeText = m.range != null ? rangePhrase(m.range) : "";
  const range = m.range == null ? "" : m.may === "cannot-target" ? ` unless ${attacking} is within ${rangeText}` : whom.includes(`within ${rangeText}`) ? "" : ` within ${rangeText}`;
  const unless = m.only_if_none != null ? `, unless there is no other eligible ${effectSubject(m.only_if_none, ctx).replace(/^all /, "").replace(/ units\b/, " unit")}` : "";
  if (m.may === "redirect") {
    const to = effectSubject(m.to, ctx);
    const what = m.kind === "stratagem" ? "Stratagems" : m.kind === "shoot" ? "ranged attacks" : m.kind === "fight" ? "melee attacks" : "attacks";
    // One unit is targeted at a time: "that target a friendly ANATHEMA PSYKANA unit".
    const one = whom.startsWith("all ") || isPlural(whom) ? `a ${whom.replace(/^all /, "").replace(/ units\b/, " unit").replace(/ models\b/, " model")}`.replace(/^a ([aeiou])/i, "an $1") : whom;
    return `${what}${m.by != null ? ` made by ${who}` : ""} that target ${one} must target ${to} instead${m.if_eligible === true ? `, if ${to} is an eligible target` : ""}`;
  }
  const except = m.except === "core-stratagems" ? " (Core Stratagems can still target it)" : "";
  // When no `by` is specified and `m.target` is the same entity as `e.target`, render passively
  // ("this unit cannot be targeted with ranged weapons") instead of "this unit cannot target this unit".
  if (m.by == null && m.target != null && m.target !== "every-eligible" && JSON.stringify(m.target) === JSON.stringify(e.target)) {
    const passive = m.may === "cannot-target" ? "cannot be targeted" : m.may === "must-target" ? "must be targeted" : "can be targeted";
    const passiveRange = m.range == null ? "" : m.may === "cannot-target" ? ` unless the attacking unit is within ${rangePhrase(m.range)}` : ` within ${rangePhrase(m.range)}`;
    return `${whom} ${passive}${kind}${passiveRange}${unless}${except}`;
  }
  // "cannot target enemy units … if the target unit was engaged with this unit at the start of the turn".
  if (m.target_condition != null) {
    const condition = describeCondition(asTargetCandidate(m.target_condition) as Condition);
    return `${who} ${verb} ${whom.replace(/^all /, "")}${kind}${range}${unless}${except} if ${condition}`;
  }
  return `${who} ${verb} ${whom}${kind}${range}${unless}${except}`;
}

/** A target_condition's this-unit is the unit checked as a target: it reads as the target unit (defender). */
function asTargetCandidate(node: unknown): unknown {
  if (node === "this-unit") return "defender";
  if (Array.isArray(node)) return node.map(asTargetCandidate);
  if (node === null || typeof node !== "object") return node;
  return Object.fromEntries(Object.entries(node as Record<string, unknown>).map(([key, value]) => [key, asTargetCandidate(value)]));
}

function countsAs(m: Record<string, unknown>, subj: string, ctx: Ctx): string {
  // "Treated as containing fewer than five models for the purpose of the [BLAST] ability".
  if (m.model_count != null) return `${subj} ${v(subj, "counts")} as containing fewer than ${jstr((m.model_count as P).below)} models for the purpose of the [${dekebab(jstr(m.for_weapon_ability)).toUpperCase()}] ability`;
  if (m.in_region != null) return `${subj} ${v(subj, "counts")} as being within ${regionPhrase(m.in_region as P)}`;
  // "for the purposes of the Psychic Guidance and Spirit Guides abilities".
  const purposes = Array.isArray(m.for_abilities) ? ` for the purposes of the ${andList([...new Set((m.for_abilities as unknown[]).map(abilityLabel))])} abilities` : "";
  return `${subj} ${v(subj, "counts")} as being within ${rangePhrase(m.within)} of ${m.of != null ? effectSubject(m.of, ctx) : "this model"}${purposes}`;
}

const CORE_RULES: Record<string, [string, string]> = {
  "benefit-of-cover": ["has the Benefit of Cover", "cannot benefit from Cover"],
  charge: ["can charge", "cannot charge"],
  advance: ["can Advance", "cannot Advance"],
  "fall-back": ["can Fall Back", "cannot Fall Back"],
  "ordered-retreat": ["is not affected by Desperate Escape tests", "must take Desperate Escape tests"],
  "fire-overwatch": ["can fire Overwatch", "cannot fire Overwatch"],
  "desperate-escape": ["must take Desperate Escape tests", "is not affected by Desperate Escape tests"],
  "attacking-ends-hidden": ["stops being hidden when it attacks", "does not stop being hidden when it attacks"],
  "engaged-shooting-hit-penalty": ["suffers the -1 to Hit for shooting while within Engagement Range", "does not suffer the -1 to Hit for shooting while within Engagement Range"],
  "charge-bonus": ["receives the Charge bonus", "does not receive the Charge bonus"],
  hidden: ["can become hidden", "cannot become hidden"],
  "orders-end-on-battle-shock": ["loses its Orders when it becomes Battle-shocked", "keeps its Orders when it becomes Battle-shocked"],
  "reserves-destruction": ["is destroyed if still in Strategic Reserves at the end of the third battle round", "is not destroyed for still being in Strategic Reserves at the end of the third battle round"],
};

function ruleState(m: Record<string, unknown>, subj: string): string {
  if (m.direction === "exchanged") {
    const first = abilityLabel(m.rule);
    const second = abilityLabel(m.exchange_with);
    return `if ${subj} ${v(subj, "has")} exactly one of the ${first} and ${second} abilities, ${subj} simultaneously ${v(subj, "loses")} that ability and ${v(subj, "gains")} the other`;
  }
  if (m.direction === "suppressed" && m.except_from === "this-ability") {
    return `${subj} ${v(subj, "loses")} the ${abilityLabel(m.rule)} ability and cannot gain it except from this ability`;
  }
  const granted = m.direction === "granted";
  const rule = jstr(m.rule);
  // any_army_faction: the granted faction rule works whatever the army's faction is.
  // "no mortal wounds are inflicted by your army's Daemonic Terror rule": one aspect of a section of the rule is off.
  if (m.sub_rule != null) return `your army's ${titleCase(jstr(m.sub_rule))} rule inflicts no mortal wounds on ${subj}`;
  if (m.rule_kind === "faction-rule") return granted ? `${subj} ${v(subj, "gains")} ${abilityLabel(m.rule)}${m.any_army_faction === true ? ", whatever your Army Faction is" : ""}` : `${subj} cannot use ${abilityLabel(m.rule)}`;
  if (rule === "overwatch-against-bearer") return `your opponent ${granted ? "can" : "cannot"} target ${subj} with Overwatch`;
  // The attacks of a bound shooting event never count against Hidden (schema: suppressed only).
  if (m.attacks != null && rule === "attacking-ends-hidden") return `those attacks do not stop ${subj} from being hidden`;
  const core = CORE_RULES[rule];
  if (m.rule_kind === "core-rule" && core) {
    const phrase = granted ? core[0] : core[1];
    if (phrase.startsWith("cannot ")) return `${noneOf(subj)} ${phrase}`;
    const agreed = phrase.replace(/^(has|is|stops|does|suffers|receives|loses|keeps) /, (w) => `${v(subj, w.trim())} `);
    return `${subj} ${isPlural(subj) ? agreed.replace(/\bits\b/g, "their") : agreed}`;
  }
  const noun = m.rule_kind === "keyword" ? "keyword" : m.rule_kind === "core-rule" ? "rule" : "ability";
  const label = m.rule_kind === "ability" ? abilityLabel(m.rule) : titleCase(rule);
  return granted ? `${subj} ${v(subj, "gains")} the ${label} ${noun}` : `${subj} ${v(subj, "loses")} the ${label} ${noun}`;
}

function abilityActivate(m: Record<string, unknown>, subj: string): string {
  const label = abilityLabel(m.ability);
  if (m.procedure === "oath") return `${subj} ${v(subj, "resolves")} the ${label} Oath procedure again`;
  const consumed = m.ignore_consumed === true ? ", even if it has already been selected this battle" : "";
  const sel = m.select as { by?: unknown; count?: unknown; from?: unknown; option_var?: unknown; excluding?: unknown } | undefined;
  const exclusive = m.exclusive === true ? " (and no other option is)" : "";
  // The option another ability's triggering use selected ("the selected combat doctrine is active for this unit").
  if (sel?.by === "event") return `the ${label} option the triggering use selected is active for ${subj}${exclusive}${consumed}`;
  if (sel != null) {
    const n = Number(sel.count ?? 1) || 1;
    const from = optionNames(sel.from);
    const how = sel.by === "roll"
      ? `make a new ${label} roll and activate ${n === 1 ? "one result" : `${n} results`} it allows${from.length ? ` among the ${orList(from)} options` : ""}`
      : `select ${n === 1 ? "one" : String(n)} ${from.length ? `of the ${orList(from)} options` : n === 1 ? "option" : "options"} of ${label}`;
    // A bound pick is made once and shared by every unit the surrounding aura or loop reaches.
    const shared = sel.option_var != null ? " (picked once and shared)" : "";
    const other = sel.excluding === "army-active" ? ", other than the one active for your army," : "";
    return `${how}${shared}${other} for ${subj}, ${m.exclusive === true ? "in place of" : "in addition to"} any already active${consumed}`;
  }
  const override = m.override as { amount?: unknown } | undefined;
  const instead = override != null ? `, using ${diceCase(override.amount)} in place of its usual amount` : "";
  if (m.all_options === true) return `every option of ${label} is active for ${subj}${consumed}`;
  if (Array.isArray(m.options)) return `the ${andList(optionNames(m.options))} options of ${label} are active for ${subj}${exclusive}${consumed}`;
  if (m.option == null) return `${subj} ${v(subj, "resolves")} the ${label} ability now${instead}`;
  // "Your unit immediately Regenerates": the option resolves once, now, rather than becoming active.
  if (m.immediate === true) return `the ${titleCase(jstr(m.option))} option of ${label} resolves now for ${subj}${instead}`;
  return `the ${titleCase(jstr(m.option))} option of ${label} is active for ${subj}${exclusive}${consumed}`;
}

/** Option ids as their display names. */
function optionNames(list: unknown): string[] {
  return Array.isArray(list) ? list.map((option) => titleCase(jstr(option))) : [];
}

/** Oath policy changes describe future procedure/reward handling, not immediate effects. */
function oathModifier(m: Record<string, unknown>, subj: string, ctx: Ctx, inline: Inline): string {
  const label = abilityLabel(m.ability);
  if (m.aspect === "quality-persistence") {
    const duration = expiryTrail(m.duration);
    return `${subj} ${v(subj, "retains")} qualities from ${jstr(m.from)} ${label} Oaths${duration ? ` ${duration}` : ""}`;
  }
  if (m.aspect === "deed-reward") {
    const method = m.selection_method === "random" ? "randomly determined " : m.selection_method === "chosen" ? "chosen " : "";
    const anyMethod = m.selection_method === "any" ? ", regardless of how those deeds were selected" : "";
    return `for ${subj}, on completion of ${jstr(m.applies_to)} ${method}${label} deeds${anyMethod}, replace their reward with: ${inline(m.effect, ctx)}`;
  }
  const domains = Array.isArray(m.domains) ? andList(m.domains.map((domain) => domain === "quality" ? "qualities" : `${jstr(domain)}s`)) : "";
  const clauses = [`when selecting ${domains} for ${label} for ${subj}`];
  if (m.exclude_previously_selected === true) clauses.push(`exclude previously selected ${domains}`);
  if (m.duplicate_roll === "choose-unselected") clauses.push("if a duplicate is rolled, choose an unselected result in that domain");
  if (m.stop_when === "all-domains-exhausted") clauses.push("stop when every domain is exhausted");
  return clauses.join("; ");
}

/** One single effect as a lowercase-initial clause. */
export function describeLeaf(e: Leaf, ctx: Ctx, inline: Inline): string {
  const m = e.modifier ?? {};
  const subj = effectSubject(e.target, ctx);
  switch (e.type) {
    case "stat-modifier": return statModifier(e, m, subj, ctx);
    case "ignore-modifiers": return ignoreModifiers(m, subj);
    case "roll-modifier": return rollModifier(m, subj, ctx);
    case "re-roll": return reRoll(e, m, subj, ctx);
    case "roll-result": return rollResult(m, subj);
    case "end-attack-sequence": return "the attack sequence ends";
    case "ability-grant": return abilityGrant(e, m, subj, ctx, inline);
    case "keyword-grant": return keywordGrant(m, subj);
    case "weapon-ability-grant": return weaponAbilityGrant(e, m, subj, ctx);
    case "weapon-ability-range": return weaponAbilityRange(m, subj);
    case "weapon-grant": {
      const count = Number(m.count ?? 1) || 1;
      return `${subj} ${v(subj, "gains")} ${count} ${weaponLabel(m.weapon_id)} weapon${count === 1 ? "" : "s"}`;
    }
    case "ability-modifier": return abilityModifier(m, subj, ctx, inline);
    case "ability-activate": return abilityActivate(m, subj);
    case "oath-modifier": return oathModifier(m, subj, ctx, inline);
    case "permission": return permission(m, subj, ctx);
    case "targeting": return targeting(e, m, subj, ctx);
    case "counts-as": return countsAs(m, subj, ctx);
    case "rule-state": return abilityClassState(e.target, m, subj) ?? ruleState(m, subj);
    case "orders-modifier": return ordersModifier(m, subj, ctx);
    case "order-share": return orderShare(m, subj, ctx);
    default: return describeShapeLeaf(e, m, subj, ctx) ?? describeBoardLeaf(e, m, subj, ctx, inline);
  }
}
